<script setup>
import { computed, onMounted, ref } from 'vue'
import QRCode from 'qrcode'
const API='http://localhost:8080/api/v1', code=ref(''), products=ref([]), loading=ref(false), error=ref(''), notice=ref(''), qrProduct=ref(null), qrImage=ref('')
const isValid=computed(()=>/^[A-Z0-9]{30}$/.test(code.value))
async function request(path,options={}){const response=await fetch(`${API}${path}`,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});if(response.status===204)return null;const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||`Request failed (${response.status})`);return body}
async function loadProducts(){loading.value=true;try{products.value=await request('/products');error.value=''}catch(e){error.value=`${e.message}. ตรวจสอบว่า Go API ทำงานอยู่ที่ localhost:8080`}finally{loading.value=false}}
function normalizeInput(){code.value=code.value.toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,30);error.value='';notice.value=''}
async function addProduct(){error.value='';notice.value='';if(!isValid.value){error.value='กรุณากรอกรหัสสินค้า A-Z หรือ 0-9 จำนวน 30 ตัวพอดี';return}try{const p=await request('/products',{method:'POST',body:JSON.stringify({code:code.value})});products.value.unshift(p);code.value='';notice.value='เพิ่มรหัสสินค้าสำเร็จ'}catch(e){error.value=e.message}}
async function showQR(p){qrProduct.value=p;qrImage.value=await QRCode.toDataURL(p.code,{width:280,margin:2,errorCorrectionLevel:'M'})}
async function deleteProduct(p){if(!window.confirm(`ยืนยันการลบรหัสสินค้า ${p.formattedCode} ?`))return;try{await request(`/products/${p.id}`,{method:'DELETE'});products.value=products.value.filter(x=>x.id!==p.id);notice.value='ลบข้อมูลสินค้าแล้ว';error.value=''}catch(e){error.value=e.message}}
onMounted(loadProducts)
</script>
<template><main class="page"><header class="topbar"><div class="brand-mark">EX</div><div><div class="eyebrow">EXAMPLE.COM · INVENTORY</div><h1>Product Code Manager</h1></div><span class="status"><i></i> Admin Console</span></header><section class="intro"><div><p class="kicker">PRODUCT MASTER DATA</p><h2>จัดการรหัสสินค้า</h2><p class="muted">เพิ่ม ดู QR Code และลบรหัสสินค้า พร้อมตรวจสอบข้อมูลซ้ำอัตโนมัติ</p></div><div class="total"><span>รหัสสินค้าทั้งหมด</span><strong>{{products.length}}</strong></div></section><section class="panel"><label for="product-code">รหัสสินค้า <span class="required">*</span></label><div class="entry-row"><input id="product-code" v-model="code" @input="normalizeInput" @keydown.enter="addProduct" placeholder="ABCDE12345ABCDE12345ABCDE12345" maxlength="30" autocomplete="off"/><button class="primary" @click="addProduct" :disabled="!isValid">＋ เพิ่มข้อมูล</button></div><div class="field-foot"><span>รองรับเฉพาะ A–Z ตัวพิมพ์ใหญ่ และตัวเลข 0–9</span><span :class="{good:isValid}">{{code.length}}/30 ตัว</span></div><div v-if="error" class="alert error">{{error}}</div><div v-if="notice" class="alert success">{{notice}}</div></section><section class="panel table-panel"><div class="table-heading"><div><h3>รายการรหัสสินค้า</h3><p class="muted">ข้อมูลบันทึกในฐานข้อมูลและเรียงตามรายการล่าสุด</p></div><button class="secondary" @click="loadProducts">↻ รีเฟรช</button></div><div class="table-wrap"><table><thead><tr><th class="id-col">ID</th><th>รหัสสินค้า (30 ตัว)</th><th class="action-col">QR Code</th><th class="action-col">จัดการ</th></tr></thead><tbody><tr v-if="loading"><td colspan="4" class="empty">กำลังโหลดข้อมูล…</td></tr><tr v-else-if="products.length===0"><td colspan="4" class="empty"><span class="empty-icon">▤</span><br/>ยังไม่มีข้อมูลสินค้า<br/><small>กรอกรหัสสินค้าด้านบนเพื่อเริ่มต้น</small></td></tr><tr v-for="p in products" :key="p.id"><td class="id-cell">{{p.id}}</td><td><code>{{p.formattedCode}}</code></td><td><button class="qr-btn" @click="showQR(p)">▦ QR</button></td><td><button class="delete-btn" @click="deleteProduct(p)">ลบ</button></td></tr></tbody></table></div><footer class="table-footer"><span>แสดง {{products.length}} รายการ</span><span>Unique product code · SQLite</span></footer></section><footer class="page-footer">© 2026 example.com <span>Interview Question 07 · Go REST API + Vue 3</span></footer><div v-if="qrProduct" class="overlay" @click.self="qrProduct=null"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="qr-title"><button class="close" aria-label="ปิด" @click="qrProduct=null">×</button><div class="modal-icon">▦</div><p class="kicker">PRODUCT IDENTIFIER</p><h2 id="qr-title">QR Code</h2><p class="muted">สแกนเพื่ออ่านรหัสสินค้า</p><div class="qr-frame"><img :src="qrImage" alt="QR Code for product"/></div><code class="modal-code">{{qrProduct.formattedCode}}</code><button class="primary full" @click="qrProduct=null">ปิดหน้าต่าง</button></section></div></main></template>
